from   plasma import pool 
import plasmaHelpers 

pool.DEFAULT_PORT  = 25333
pool.validate_name = plasmaHelpers.validate_name

def main():
  pool_name = "tcp://localhost/hello"

  # Connect to the pool
  hose = pool.participate(pool_name)
  if hose is None:
    print(f"Failed to connect to pool: {pool_name}")
    return 1

  try:
    while True:
      protein = hose.Next()  # Waits indefinitely
      if protein.IsNull():
        print("Error: received null protein")
        break

      print(protein.ToSlaw().ToString())
  finally:
    hose.Withdraw()

if __name__ == "__main__":
  main()

### end ###
